            topTituloObelisco: 'Obelisco e Teatro Colón',
            topObelisco: 'Admire o icônico Obelisco de Buenos Aires e aproveite a cultura do Teatro Colón.',
            topTituloTorreEiffel: 'Torre Eiffel',
            topTorreEiffel: 'O símbolo mais famoso da França e um dos monumentos mais fotografados do planeta.',
            topTituloCristo: 'Cristo Redentor',
            topCristo: 'Viva uma experiência inesquecível visitando uma das estátuas mais famosas do mundo.',
            topTituloTorresPaine: 'Torres del Paine',
            topTorresPaine: 'Descubra montanhas e paisagens impressionantes no sul do Chile.',
            topTituloCartagena: 'Cartagena',
            topCartagena: 'Passeie por ruas cheias de história e arquitetura colonial.',
            topTituloJapon: 'Fuji / Sensoji / Shibuya',
            topJapon: 'Explore a cultura japonesa entre templos e cidades modernas.',
            topTituloMachuPicchu: 'Machu Picchu',
            topMachuPicchu: 'Descubra a majestosidade da antiga cidade inca cercada por montanhas e paisagens impressionantes. Viva uma experiência única cheia de história e cultura.',
            topTituloPetra: 'Petra',
            topPetra: 'Contemple o majestoso monumento esculpido na rocha, joia arquitetônica da Jordânia.',
            topTituloChichen: 'Chichén Itzá',
            topChichen: 'Admire uma das cidades maias mais impressionantes, famosa por sua pirâmide e seu incrível legado arqueológico.',
            topTituloTimesSquare: 'Times Square',
            topTimesSquare: 'O coração iluminado de Nova York e um dos lugares urbanos mais movimentados do mundo.',
            topDescObelisco: 'O Obelisco é o principal símbolo de Buenos Aires, localizado na interseção das avenidas 9 de Julio e Corrientes. O Teatro Colón é um dos teatros de ópera mais importantes do mundo, com acústica excepcional e arquitetura majestosa. Este pacote inclui uma visita guiada por ambos os monumentos, com entrada no teatro e um passeio pelos arredores da cidade.',
            topDescTorreEiffel: 'Construída por Gustave Eiffel para a Exposição Universal de 1889, a Torre Eiffel é o monumento mais emblemático de Paris. Com seus 330 metros de altura, oferece uma vista panorâmica incomparável da cidade. Você pode subir aos seus três níveis, desfrutar de um restaurante com vista e aprender sobre sua história no museu interativo.',
            topDescCristo: 'O Cristo Redentor é uma estátua de 30 metros que coroa o morro do Corcovado no Rio de Janeiro. É um dos símbolos mais reconhecidos do Brasil e do cristianismo. A viagem inclui a subida de trem até o topo, onde você poderá desfrutar de uma vista espetacular da cidade e da baía de Guanabara.',
            topDescTorresPaine: 'O Parque Nacional Torres del Paine é um paraíso para os amantes de trekking e da natureza. Seus imponentes picos de granito, geleiras, lagos turquesa e fauna autóctone (guanacos, condores) o tornam um destino único na Patagônia chilena. O pacote inclui excursões guiadas e hospedagem no parque.',
            topDescCartagena: 'Cartagena das Índias é uma joia colonial na costa caribenha da Colômbia. Suas muralhas, ruas de paralelepípedos, praças e casas coloridas transportam você ao passado. A cidade oferece uma mistura de história, cultura, gastronomia e praias próximas. O passeio inclui visita ao Castelo de San Felipe, ao centro histórico e um passeio de chiva.',
            topDescJapon: 'O Japão é um país que combina tradição e modernidade à perfeição. Neste pacote você visitará o Monte Fuji, o templo Sensoji em Tóquio e o famoso cruzamento de Shibuya. Você aproveitará a cultura japonesa, sua gastronomia e suas paisagens únicas. Inclui transporte em trem-bala, hospedagem e guia local.',
            topDescMachuPicchu: 'Machu Picchu é uma das maravilhas do mundo e o legado mais impressionante do Império Inca. Localizado no topo de uma montanha no Peru, este santuário histórico oferece vistas de tirar o fôlego e uma arquitetura em perfeita harmonia com o ambiente. A viagem inclui o trem desde Cusco, entrada na cidadela e guia especializado.',
            topDescPetra: 'Petra é a antiga cidade nabateia escavada na rocha rosa, situada no deserto da Jordânia. Seu monumento mais famoso é o Tesouro (Al-Khazneh), mas o local inclui tumbas, templos e um teatro romano. O pacote inclui uma caminhada guiada pelo desfiladeiro de Siq, visita ao Tesouro e ao Mosteiro, e hospedagem em Wadi Musa.',
            topDescChichen: 'Chichén Itzá é a cidade maia mais famosa da península de Yucatán. Sua pirâmide de Kukulcán é uma maravilha da astronomia e da arquitetura. O passeio inclui o Cenote Sagrado, o Jogo de Bola e o Observatório. Você aprenderá sobre a cultura maia com um guia especialista e aproveitará a gastronomia local.',
            topDescTimesSquare: 'Times Square é o epicentro da cidade de Nova York, conhecido por suas gigantescas telas de publicidade, teatros da Broadway e agitação constante. É o lugar mais visitado dos Estados Unidos e oferece uma energia incomparável. O pacote inclui um passeio a pé pelos arredores, entrada em um espetáculo da Broadway e hospedagem em Midtown.',
            topFactsObelisco: 'Localização: Buenos Aires, Argentina|Altura: 67 metros|Ano: 1936|Visitantes: 2 milhões/ano',
