            aboutTagline: 'Conectando viajantes com o mundo desde o Panamá',
            aboutQueEs: 'O que é a KAVARI?',
            aboutDesc1: 'A KAVARI é uma plataforma digital de turismo inteligente que conecta os viajantes a informações reais, guias certificados e destinos ao redor do mundo. Nossa missão é fazer com que planejar uma viagem seja uma experiência simples, confiável e emocionante.',
            aboutDesc2: 'Nascemos com a ideia de que viajar não deve ser complicado. Com a KAVARI, os usuários têm acesso a informações atualizadas sobre destinos, companhias aéreas, hospedagens, gastronomia, cultura e muito mais, tudo em um só lugar.',
            aboutMisionLabel: 'Nossa Missão',
            aboutMision: 'Missão',
            aboutMisionText: 'Facilitar o acesso à informação turística de qualidade, conectando os viajantes a guias locais certificados e oferecendo ferramentas digitais que transformem a forma como o mundo se desloca, de maneira segura, acessível e emocionante.',
            aboutVisionLabel: 'Nossa Visão',
            aboutVision: 'Visão',
            aboutVisionText: 'Nos tornar a plataforma de turismo inteligente de referência na América Latina, reconhecida pela qualidade de suas informações, pela autenticidade de suas experiências e pelo impacto positivo que gera nas comunidades locais de cada destino.',
