            faqViajerosTitulo: 'Perguntas frequentes — Viajantes',
            faqGuiasTitulo: 'Perguntas frequentes — Guias turísticos',
            faqPlataformaTitulo: 'Perguntas frequentes — A plataforma',
            faqPaquetesTitulo: 'Perguntas frequentes — Pacotes de viagem',
            faq1q: 'Como faço para buscar um destino turístico no KAVARI?',
            faq1a: 'Na página de Destinos você encontra os 36 países disponíveis no KAVARI. Você pode usar o buscador no topo para filtrar por nome de país ou cidade. Clique em "Ver destino" para acessar todas as informações turísticas desse país: cultura, gastronomia, aventura, companhias aéreas, hospedagens e mais.',
            faq2q: 'Posso contratar um guia turístico pelo KAVARI?',
            faq2a: 'Sim. Dentro de cada página de país você encontra a seção "Guias Turísticos" com os guias certificados disponíveis para esse destino. Filtre por nível (Diamante, Ouro, Prata) e clique em "Contratar" para enviar sua solicitação diretamente ao guia.',
            faq3q: 'Os preços exibidos são definitivos?',
            faq3a: 'Os preços de companhias aéreas e hospedagens são preços de referência na temporada média. Os preços finais podem variar conforme as datas, a disponibilidade e a origem do voo. Ao clicar em "Reservar voo" ou "Reservar hospedagem", você será redirecionado diretamente à companhia aérea ou hospedagem para confirmar o preço final.',
            faq4q: 'Que informações práticas posso encontrar sobre cada país?',
            faq4a: 'Na seção "Info prática" de cada país você encontra: moeda local, idioma oficial, vistos e documentos necessários, transporte, conectividade Wi-Fi, melhores épocas para viajar e um itinerário sugerido. Você também pode usar o Assistente de IA para fazer perguntas específicas sobre o destino.',
            faq5q: 'Como funciona o Assistente de IA do KAVARI?',
            faq5a: 'Cada página de país tem um chatbot especializado nesse destino. Você pode perguntar sobre clima, vistos, segurança, gastronomia, custos, transporte, emergências e mais. O assistente responde com informações específicas do país selecionado. Use as sugestões predefinidas para começar ou escreva sua própria pergunta.',
            faq6q: 'Como me cadastro como guia turístico no KAVARI?',
            faq6a: 'Clique no botão "Sou Guia" na página inicial ou visite a seção de Guias e selecione "Quero ser guia". Preencha seu perfil com nome, descrição, idiomas, especialidades, cidade e país onde você atua. Escolha seu nível de assinatura (Prata, Ouro ou Diamante) e faça o pagamento para ativar seu perfil.',
            faq7q: 'Quais são as diferenças entre os níveis Prata, Ouro e Diamante?',
            faq7a: '<strong>Prata ($20/mês):</strong> Visibilidade padrão nas listagens de guias. <br><strong>Ouro ($35/mês):</strong> Melhor posicionamento nos resultados de busca e perfil em destaque. <br><strong>Diamante ($50/mês):</strong> Prioridade máxima nas listagens, selo especial e aparece primeiro para os viajantes. Guias Diamante e Ouro aparecem ordenados antes dos de Prata.',
            faq8q: 'Em quais países posso me registrar como guia?',
            faq8a: 'Você pode se registrar como guia para qualquer um dos 36 destinos disponíveis no KAVARI. Ao selecionar seu país durante o cadastro, seu perfil aparecerá automaticamente na seção "Guias Turísticos" desse país. Se você atua em vários países, pode criar perfis separados para cada um.',
            faq9q: 'Quais formas de pagamento o KAVARI aceita?',
            faq9a: 'Para o pagamento das assinaturas de guia aceitamos: Yappy (banco móvel do Panamá), Transferência bancária (Banco General, BAC, Banistmo) e Cartão de crédito/débito (Visa, Mastercard, American Express). Todos os pagamentos são protegidos com criptografia SSL.',
            faq10q: 'Em quais idiomas o KAVARI está disponível?',
            faq10a: 'O KAVARI está disponível em Espanhol, Inglês e Português. Você pode mudar o idioma a qualquer momento usando o seletor de idioma (ícone 🌐) disponível na barra de navegação de todas as páginas. Sua preferência é salva automaticamente para a sua próxima visita.',
            faq11q: 'Como ativo o modo escuro?',
            faq11a: 'Clique no ícone 🌙 em qualquer barra de navegação do KAVARI para ativar o modo escuro. Você também pode usar o ícone ☀️ para voltar ao modo claro. Sua preferência é salva automaticamente e aplicada em todas as páginas da plataforma.',
            faq12q: 'Como funciona o tutorial da plataforma?',
            faq12a: 'O tutorial interativo aparece automaticamente na primeira vez que você visita o KAVARI. Ele guia você passo a passo por todas as funcionalidades da plataforma com mensagens pop-up, setas e exemplos. Se quiser revê-lo, clique no botão "Tutorial" no menu principal da página inicial.',
            faq13q: 'O que um pacote de viagem do KAVARI inclui?',
            faq13a: 'Cada pacote é diferente, mas geralmente incluem: voo internacional (nos pacotes internacionais), hotel de 3 ou 4 estrelas, traslados aeroporto-hotel, guia turístico certificado, café da manhã diário e ingressos para as principais atrações. Clique em "Ver detalhes" em qualquer pacote para ver exatamente o que esse itinerário inclui.',
            faq14q: 'Posso reservar diretamente pelo KAVARI?',
            faq14a: 'Atualmente, o KAVARI funciona como plataforma de informações e diretório turístico. Ao clicar em "Reservar agora", você será direcionado para ver o destino completo e coordenar com guias locais. Para reservas de voos e hotéis, os links redirecionam você diretamente para as companhias aéreas e o Airbnb. Para pacotes completos, entre em contato conosco pelo formulário de Contato.',
            ayudaCTATitulo: 'Não encontrou o que procurava?',
            ayudaCTADesc: 'Nossa equipe está pronta para ajudá-lo com qualquer dúvida sobre destinos, guias ou a plataforma.',
