            tutorialSobrenosotrosTitulo_5: 'O que é o KAVARI?',
            tutorialSobrenosotrosDesc_5: 'Esta seção explica nossa missão como plataforma de turismo inteligente. Conectamos viajantes com informações reais, guias certificados e destinos ao redor do mundo.',
            tutorialSobrenosotrosTitulo_6: 'Missão e Visão',
            tutorialSobrenosotrosDesc_6: 'Dois cartões que resumem nossos valores: facilitar o acesso a informações turísticas de qualidade e nos tornarmos referência na América Latina.',
            tutorialSobrenosotrosTitulo_7: 'Nossa Equipe',
            tutorialSobrenosotrosDesc_7: 'Cada membro tem uma função específica: programação, design, comunicação e apresentação. Todos trabalhamos para tornar o KAVARI possível.',
