paisPanama_nombre: 'Panamá',
paisPanama_subtitulo: 'Infinita',
paisPanama_tagline: 'Onde o Pacífico abraça o Atlântico',
paisPanama_descripcion: 'Maravilhas da engenharia, culturas ancestrais, selvas virgens e praias remotas em um território extraordinário de 75.517 km². O istmo que une dois continentes e separa dois oceanos.',
paisPanama_continente: 'América Central',
paisPanama_moneda: 'Dólar americano (USD) / Balboa (PAB)',
paisPanama_idioma: 'Espanhol',
paisPanama_capital: 'Cidade do Panamá',
paisPanama_poblacion: '4.404.108',
paisPanama_zona_horaria: 'UTC-5',
paisPanama_codigo_telefonico: '+507',
paisPanama_stats_0_label: 'km² de território',
paisPanama_stats_1_label: 'Espécies de flora',
paisPanama_stats_2_label: 'Vulcão Barú',
paisPanama_stats_3_label: 'Visitantes por ano',
paisPanama_ticker_0: 'Canal do Panamá | 80 km entre dois oceanos',
paisPanama_ticker_1: 'San Blas | 365 ilhas administradas pelo povo Guna',
paisPanama_ticker_2: 'Vulcão Barú | 3.475 m, ponto mais alto do país',
paisPanama_ticker_3: 'Café Geisha | 6.034 USD por quilo em leilão',
paisPanama_ticker_4: 'Bocas del Toro | 9 ilhas principais no Caribe',
paisPanama_ticker_5: 'Darién | Patrimônio Natural da Humanidade UNESCO',
paisPanama_ticker_6: 'Aves do Panamá | 1.026 espécies registradas',
paisPanama_ticker_7: 'Povos originários | 7 culturas indígenas vivas',
paisPanama_quickFacts_0_titulo: 'Ponte biológica entre continentes',
paisPanama_quickFacts_0_texto: 'O istmo panamenho emergiu do mar há 3,5 milhões de anos, unindo a América do Norte à América do Sul e permitindo o Grande Intercâmbio Biótico Americano.',
paisPanama_quickFacts_1_titulo: 'Único lugar com vista para dois oceanos',
paisPanama_quickFacts_1_texto: 'Do topo do Vulcão Barú (3.475 m), em dias claros, é possível ver simultaneamente o Oceano Pacífico e o Mar do Caribe. É o único lugar do planeta onde isso é possível.',
paisPanama_quickFacts_2_titulo: 'Dólar americano como moeda oficial',
paisPanama_quickFacts_2_texto: 'Desde 1904, o Panamá utiliza o dólar (USD) como moeda de curso legal. O Balboa (PAB) existe apenas em moedas fracionárias com paridade 1:1.',
paisPanama_quickFacts_3_titulo: 'Recorde mundial de observação de aves',
paisPanama_quickFacts_3_texto: 'O Panamá detém o recorde mundial do Christmas Bird Count com 357 espécies de aves avistadas em um único dia. O país abriga mais espécies de aves do que toda a América do Norte.',
paisPanama_destinos_canal_nombre: 'Canal do Panamá',
paisPanama_destinos_canal_tag: 'Engenharia · Maravilha do mundo moderno',
paisPanama_destinos_canal_descripcion: 'Oitenta quilômetros de via aquática que conectam o Pacífico e o Atlântico. Inaugurado em 15 de agosto de 1914, movimenta 6% do comércio marítimo mundial, com entre 36 e 38 navios transitando diariamente.',
paisPanama_destinos_canal_detalle: 'O Canal do Panamá é uma das sete maravilhas da engenharia moderna segundo a ASCE. Possui três conjuntos de eclusas: Miraflores (2 câmaras), Pedro Miguel (1 câmara) e Gatún (3 câmaras). A ampliação de 2016 acrescentou as eclusas de Cocolí (Pacífico) e Agua Clara (Atlântico). O pedágio mais alto já registrado foi de 1.201.777 USD, pago pelo navio Ever Max em 2023.',
paisPanama_destinos_canal_consejo: 'Visite de manhã cedo para ver o maior tráfego de navios',
paisPanama_destinos_casco_nombre: 'Casco Antiguo',
paisPanama_destinos_casco_tag: 'Patrimônio UNESCO · Fundado em 1673',
paisPanama_destinos_casco_descripcion: 'O coração histórico da Cidade do Panamá. Fundado após a destruição da Panamá La Vieja pelo pirata Henry Morgan em 1671. Ruas de pedra, igrejas barrocas, praças coloniais e restaurantes de classe mundial.',
paisPanama_destinos_casco_detalle: 'Declarado Patrimônio da Humanidade pela UNESCO em 1997. A Catedral Metropolitana levou 108 anos para ser construída (1688-1796). A Igreja de San José abriga o famoso Altar de Ouro. O Arco Chato permaneceu de pé sem colunas por 350 anos, até um incêndio.',
paisPanama_destinos_casco_consejo: 'Suba a um terraço ao pôr do sol para ver o skyline se iluminar',
paisPanama_destinos_sanblas_nombre: 'Arquipélago de San Blas',
paisPanama_destinos_sanblas_tag: 'Caribe · Comarca Guna Yala',
paisPanama_destinos_sanblas_descripcion: 'Trezentas e sessenta e cinco ilhas de areia branca e águas turquesa, administradas com plena soberania pelo povo indígena Guna. Apenas 49 são habitadas.',
paisPanama_destinos_sanblas_detalle: 'O povo Guna Yala mantém sua autonomia política desde a Revolução Guna de 1925. A hospedagem é feita em cabanas rústicas. O acesso principal é de avião leve a partir de Albrook (30-45 minutos) ou por estrada 4x4 (3 horas até Cartí).',
paisPanama_destinos_sanblas_consejo: 'Leve dólares em dinheiro. Não há caixas eletrônicos',
paisPanama_destinos_boquete_nombre: 'Boquete, Chiriquí',
paisPanama_destinos_boquete_tag: 'Montanha · Café · Aventura',
paisPanama_destinos_boquete_descripcion: 'Vale de flores e café gourmet a 1.000 metros acima do nível do mar, nas encostas do Vulcão Barú. Clima primaveril o ano todo.',
paisPanama_destinos_boquete_detalle: 'A Hacienda La Esmeralda popularizou a variedade Geisha em 2004. O Vulcão Barú (3.475 m) oferece a única vista do mundo onde é possível ver simultaneamente o Pacífico e o Atlântico. A subida noturna leva entre 6 e 8 horas.',
paisPanama_destinos_boquete_consejo: 'Melhor época para a subida: janeiro-abril',
paisPanama_destinos_bocas_nombre: 'Bocas del Toro',
paisPanama_destinos_bocas_tag: 'Caribe · Arquipélago de 9 ilhas',
paisPanama_destinos_bocas_descripcion: 'Um arquipélago vibrante no Caribe panamenho. Surf de classe mundial em Playa Bluff, snorkel com tubarões-lixa em Cayo Coral.',
paisPanama_destinos_bocas_detalle: 'O arquipélago é formado por 9 ilhas principais. Em Cayo Coral é possível fazer snorkel com tubarões-lixa a 6 metros. A rã venenosa-de-morango é endêmica da Isla Bastimentos.',
paisPanama_destinos_bocas_consejo: 'Maio e novembro: menor ocupação com bom clima',
paisPanama_destinos_taboga_nombre: 'Ilha Taboga',
paisPanama_destinos_taboga_tag: 'Pacífico · Passeio de um dia',
paisPanama_destinos_taboga_descripcion: 'A apenas vinte minutos de ferry da Cidade do Panamá. Conhecida como a Ilha das Flores, oferece praias tranquilas e a Igreja de San Pedro.',
paisPanama_destinos_taboga_detalle: 'A Igreja de San Pedro foi fundada em 1524. As trilhas sobem até o cerro Vigía e o cerro de la Cruz. Avistamento de baleias-jubarte de julho a outubro.',
paisPanama_destinos_taboga_consejo: 'Compre o bilhete com antecedência nos fins de semana',
paisPanama_destinos_darien_nombre: 'Parque Nacional Darién',
paisPanama_destinos_darien_tag: 'UNESCO · Mata primária',
paisPanama_destinos_darien_descripcion: 'Patrimônio Natural da Humanidade desde 1981. Uma das florestas tropicais mais biodiversas do planeta.',
paisPanama_destinos_darien_detalle: 'O Darién conecta a América Central à América do Sul. As comunidades Emberá e Wounaan são guardiãs do território. Expedições de 3 a 7 dias.',
paisPanama_destinos_darien_consejo: 'Contrate guias locais certificados',
