paisPanama_destinos_perlas_tag: 'Pacífico · Luxo · Natureza',
paisPanama_destinos_perlas_descripcion: 'Noventa ilhas e ilhotas no Pacífico panamenho. Pesca esportiva de marlim e resorts de luxo na Isla Contadora.',
paisPanama_destinos_perlas_detalle: 'O arquipélago deve seu nome às pérolas extraídas por séculos. A Isla Contadora concentra os resorts. Pesca de marlim-azul: novembro a março.',
paisPanama_destinos_perlas_consejo: 'Reserve com antecedência na alta temporada',
