paisPanama_cultura_items_carnaval_nombre: 'Carnaval de Las Tablas',
paisPanama_cultura_items_carnaval_tag: 'Festividade · Província de Los Santos',
paisPanama_cultura_items_carnaval_descripcion: 'Considerado um dos carnavais mais autênticos da América Latina. Os blocos Calle Arriba e Calle Abajo competem com carros alegóricos monumentais.',
paisPanama_cultura_items_carnaval_detalle: 'A rivalidade entre Calle Arriba e Calle Abajo define a identidade de Las Tablas. Os \'culecos\' são batalhas de água. Atrai mais de 100.000 visitantes todos os anos, em fevereiro.',
paisPanama_cultura_items_molas_nombre: 'Molas Guna',
paisPanama_cultura_items_molas_tag: 'Arte têxtil · Povo Guna',
paisPanama_cultura_items_molas_descripcion: 'Arte têxtil criado com a técnica do \'appliqué inverso\': camadas de tecido recortadas para revelar desenhos geométricos.',
paisPanama_cultura_items_molas_detalle: 'Cada mola pode levar entre duas e seis semanas. Os desenhos representam natureza, mitologia Guna e padrões geométricos. Reconhecidas pela UNESCO.',
