paisPanama_cultura_items_pollera_tag: 'Traje nacional · Símbolo pátrio',
paisPanama_cultura_items_pollera_descripcion: 'Considerado um dos trajes nacionais mais elaborados do mundo. Bordado à mão com fios de seda e joias de ouro.',
paisPanama_cultura_items_pollera_detalle: 'Uma pollera de gala custa entre 5.000 e 25.000 USD. É exibida durante as Fiestas Patrias de novembro e o Festival Nacional de la Pollera.',
