paisPanama_cultura_items_pueblos_descripcion: 'Sete povos indígenas com territórios autônomos: Ngäbe, Guna, Buglé, Emberá, Wounaan, Naso e Bri Bri.',
paisPanama_cultura_items_pueblos_detalle: 'Cada povo preserva sua língua e sistemas de governo. As seis comarcas cobrem 20% do território nacional.',
