paisMexico_nombre: 'México',
paisMexico_subtitulo: 'Vibrante',
paisMexico_tagline: 'País de mil culturas, onde o passado e o futuro se encontram',
paisMexico_descripcion: 'O México é o terceiro maior país da América Latina, com 1,96 milhão de km². Localizado no norte da América Central, combina costas selvagens, desertos, montanhas nevadas e mais de 3.000 anos de história civilizatória. É a maior economia da região e o país com mais falantes de espanhol no mundo.',
