paisMexico_gastronomia_platos_0_categoria: 'Comida rápida · Prato icônico',
paisMexico_gastronomia_platos_0_descripcion: 'Carne de porco marinada assada no espeto em estilo shawarma, servida com abacaxi, cebola, coentro e molho.',
