paisMexico_gastronomia_platos_1_categoria: 'Prato tradicional · Molho',
paisMexico_gastronomia_platos_1_descripcion: 'Molho complexo de pimentas, cacau, especiarias, frutas e sementes, servido com frango ou peru.',
paisMexico_gastronomia_platos_1_nota: 'Origem: Oaxaca, requer 30+ ingredientes',
