paisMexico_gastronomia_platos_3_categoria: 'Sopa · Tradição',
paisMexico_gastronomia_platos_3_descripcion: 'Caldo de milho cacahuazintle com carne de porco, servido com alface, rabanete, cebola e tostadas.',
paisMexico_gastronomia_platos_3_nota: 'Tradição: quintas e fins de semana',
