paisMexico_gastronomia_platos_6_categoria: 'Frutos do mar · Entrada',
paisMexico_gastronomia_platos_6_descripcion: 'Peixe ou camarão marinado no limão com tomate, cebola, coentro, pimenta e abacate.',
paisMexico_gastronomia_platos_6_nota: 'Popular nas costas do Pacífico',
