paisMexico_souvenirs_2_productos_4_descripcion: 'Garrafa de mezcal com lagarta de maguey, produzido por destiladores locais de Oaxaca. Sabor defumado e tradição ancestral.',
paisMexico_aerolineas_0_descripcion: 'A companhia aérea de bandeira do México. Conexões para toda a América Latina, América do Norte e Europa. Membro da SkyTeam.',
paisMexico_aerolineas_1_descripcion: 'A maior companhia aérea de ultra baixo custo do México. Tarifas econômicas com ampla rede de destinos nacionais e internacionais.',
paisMexico_aerolineas_2_descripcion: 'Companhia aérea mexicana de baixo custo com base em Monterrey. Conexões para os Estados Unidos, América Central e o Caribe.',
paisMexico_aerolineas_3_descripcion: 'Voos diretos de várias cidades dos EUA para os principais destinos turísticos do México via Dallas e Miami.',
paisMexico_aerolineas_4_descripcion: 'Conexões diretas de Houston, Chicago e Denver para Cancún, Cidade do México e Los Cabos. Ampla rede norte-americana.',
