paisPeru_nombre: 'Peru',
paisPeru_subtitulo: 'Místico',
paisPeru_tagline: 'País de litoral, serra e floresta, onde a história e a natureza se encontram',
paisPeru_descripcion: 'Peru é um país de grande diversidade geográfica e cultural, com litoral, Andes e Amazônia, uma superfície de 1.285.215 km² e uma população projetada de 34,34 milhões em 2024. Sua capital é Lima, sua moeda é o sol, e o espanhol convive com línguas originárias como quíchua e aimará.',
paisPeru_continente: 'América do Sul',
paisPeru_moneda: 'Sol peruano (PEN)',
paisPeru_idioma: 'Espanhol (oficial), 40+ línguas originárias (quíchua, aimará)',
