paisPeru_gastronomia_platos_1_categoria: 'Fusão · Prato popular',
paisPeru_gastronomia_platos_1_descripcion: 'Tiras de lombo bovino salteadas com cebola, tomate, pimenta amarela e batatas fritas. Acompanhado de arroz.',
