paisPeru_gastronomia_platos_2_descripcion: 'Creme de pimenta amarela com frango desfiado, nozes e queijo. Servido com arroz e batata cozida.',
paisPeru_gastronomia_platos_2_nota: 'Origem colonial, inspirado na sopa espanhola',
