paisPeru_gastronomia_platos_3_descripcion: 'Espetos de coração bovino marinado em vinagre e pimenta panca, grelhados na brasa.',
paisPeru_gastronomia_platos_3_nota: 'Ícone da comida de rua',
paisPeru_gastronomia_platos_4_nombre: 'Pachamanca',
paisPeru_gastronomia_platos_4_categoria: 'Cozimento ancestral · Andina',
paisPeru_gastronomia_platos_4_descripcion: 'Carnes, batatas, favas, batata-doce e humitas cozidos sob a terra com pedras quentes.',
paisPeru_gastronomia_platos_4_nota: 'Tradição pré-inca do Vale do Mantaro',
