paisPeru_gastronomia_platos_5_descripcion: 'Camadas de batata amarela temperada com limão e pimenta, recheadas com frango, atum ou frutos do mar.',
paisPeru_gastronomia_platos_5_nota: 'Nome ligado à Guerra do Pacífico',
