paisPeru_gastronomia_platos_6_descripcion: 'Rocoto (pimenta grande) recheado com carne bovina e suína, passas, nozes e queijo, gratinado no forno.',
paisPeru_gastronomia_platos_6_nota: 'Especialidade de Arequipa',
