paisPeru_gastronomia_platos_7_descripcion: 'Arroz com frango, azeitonas, ovo e especiarias, embrulhado em folha de bijao e cozido.',
paisPeru_gastronomia_platos_7_nota: 'Celebração de São João Batista (24 de junho)',
