paisPeru_aventura_titulo: 'Aventura & Natureza no Peru',
paisPeru_aventura_descripcion: 'O Peru se destaca pela sua diversidade ecológica, com litoral desértico, altos Andes e Amazônia tropical. É um dos 17 países megadiversos do planeta.',
