paisArgentina_hospedajes_0_tipo: 'Loft inteiro',
paisArgentina_hospedajes_0_descripcion: 'Loft restaurado do século XIX no bairro mais tradicional de Buenos Aires. Perto da Feira de San Telmo e do tango.',
paisArgentina_hospedajes_1_nombre: 'Apartamento Moderno em Palermo',
paisArgentina_hospedajes_1_tipo: 'Apartamento inteiro',
paisArgentina_hospedajes_1_descripcion: 'Moderno apartamento no bairro mais descolado de Buenos Aires. Perto de parques, restaurantes e vida noturna.',
paisArgentina_hospedajes_2_nombre: 'Casa de Campo em Chacras de Coria',
paisArgentina_hospedajes_2_tipo: 'Casa inteira',
paisArgentina_hospedajes_2_descripcion: 'Casa de campo cercada por vinhedos em Mendoza. Piscina, jardim e vistas para os Andes. Ideal para amantes do vinho.',
paisArgentina_hospedajes_3_nombre: 'Cabana de frente para o lago em Bariloche',
paisArgentina_hospedajes_3_tipo: 'Cabana privativa',
paisArgentina_hospedajes_3_descripcion: 'Cabana com vista para o lago Nahuel Huapi e lareira. Perto do centro de esqui Catedral e do Circuito Chico.',
paisArgentina_hospedajes_4_nombre: 'Eco-lodge em El Calafate',
paisArgentina_hospedajes_4_tipo: 'Cabana ecológica',
paisArgentina_hospedajes_4_descripcion: 'Cabana sustentável com vista para o Glaciar Perito Moreno. Aquecimento, terraço e ambiente natural da Patagônia.',
paisArgentina_hospedajes_5_nombre: 'Casa Austral em Ushuaia',
paisArgentina_hospedajes_5_tipo: 'Casa inteira',
paisArgentina_hospedajes_5_descripcion: 'Casa com vista para o Canal Beagle e para a cidade do Fim do Mundo. Perto do Parque Nacional Tierra del Fuego.',
paisBrasil_nombre: 'Brasil',
paisBrasil_subtitulo: 'Vibrante',
paisBrasil_tagline: 'Gigante sul-americano de praias, florestas e cultura viva',
paisBrasil_descripcion: 'O Brasil é o maior país da América do Sul, conhecido por sua enorme diversidade natural, cultural e turística. Tem florestas tropicais, grandes cidades, litoral atlântico e uma das economias mais importantes da região.',
paisBrasil_continente: 'América do Sul',
