paisChile_nombre: 'Chile',
paisChile_subtitulo: 'Austral',
paisChile_tagline: 'Um país longo, diverso e cheio de paisagens únicas',
paisChile_descripcion: 'O Chile fica na América do Sul e se estende ao longo do extremo ocidental do continente, entre a Cordilheira dos Andes e o oceano Pacífico. Tem uma área de 756.700 km², uma população de 19.764.771 habitantes (2024), capital em Santiago, moeda peso chileno e fuso horário de UTC−3 a UTC−6 conforme a região.',
