paisChile_ticker_0: 'Chile | País mais longo do mundo: 4.300 km de norte a sul',
paisChile_ticker_1: 'Deserto do Atacama | O deserto mais seco do planeta',
paisChile_ticker_2: 'Torres del Paine | 8ª maravilha do mundo',
paisChile_ticker_3: 'Ilha de Páscoa | Moais e cultura Rapa Nui (UNESCO)',
