paisCuba_cultura_darkBand_datos_2_label: 'revolução cubana',
paisCuba_gastronomia_titulo: 'Gastronomia de Cuba',
paisCuba_gastronomia_descripcion: 'A culinária cubana combina influências espanholas e africanas, com uso frequente de arroz, feijão, porco, banana, mandioca e especiarias. É uma cozinha saborosa e consistente.',
