paisCuba_gastronomia_platos_0_categoria: 'Prato nacional',
paisCuba_gastronomia_platos_0_descripcion: 'Carne desfiada em molho de tomate, cebola, pimentão e cominho. Servida com arroz, feijão preto e banana-da-terra madura frita.',
