paisCuba_aventura_titulo: 'Aventura & Natureza em Cuba',
paisCuba_aventura_descripcion: 'Cuba oferece costas extensas (mais de 5.000 km de litoral), cayos, vales, montanhas e áreas de floresta tropical, com forte foco em turismo de praia, natureza e cultura.',
paisCuba_aventura_stats_0_label: 'km de litoral',
paisCuba_aventura_stats_1_label: 'Cayos e ilhotas',
paisCuba_aventura_stats_2_label: 'Pico Turquino',
paisCuba_aventura_stats_3_label: 'Território protegido',
paisCuba_aventura_actividades_0_nombre: 'Banho de praia e snorkel em cayos',
paisCuba_aventura_actividades_0_descripcion: 'Varadero, Cayo Coco, Cayo Santa María, Praia Ancón, Guardalavaca. Águas turquesa e areia branca. Snorkel em recifes de coral.',
paisCuba_aventura_actividades_1_nombre: 'Trilhas em Viñales',
paisCuba_aventura_actividades_1_descripcion: 'Caminhadas entre mogotes, cavalgadas, visita a plantações de tabaco, cavernas e mural da pré-história.',
