paisCuba_aventura_actividades_3_descripcion: 'Casa da Trova, Castelo do Morro, Quartel Moncada, Carnaval (julho), música ao vivo.',
paisCuba_aventura_actividades_4_nombre: 'Ascensão ao Pico Turquino',
paisCuba_aventura_actividades_4_descripcion: 'Montanha mais alta de Cuba (1.974 m). Trekking na Sierra Maestra, lugar histórico da Revolução.',
paisCuba_aventura_actividades_5_nombre: 'Mergulho em Jardines de la Reina',
paisCuba_aventura_actividades_5_descripcion: 'Parque Nacional marinho, um dos melhores locais de mergulho do Caribe. Tubarões, tartarugas, corais.',
paisCuba_aventura_darkBand_titulo: 'A maior ilha do Caribe',
paisCuba_aventura_darkBand_texto: 'Cuba é o país mais extenso do Caribe. Tem mais de 5.000 km de litoral, 4.000 cayos e uma biodiversidade única. 25% do seu território é área natural protegida.',
