paisCuba_historia_cronologia_0_texto: 'Cristóvão Colombo chega à ilha, marcando o início da colonização espanhola.',
paisCuba_historia_cronologia_1_titulo: 'Fundação de Havana',
paisCuba_historia_cronologia_1_texto: 'Havana é fundada em sua localização atual. Tornou-se um porto-chave do Império Espanhol.',
paisCuba_historia_cronologia_2_titulo: 'Início da república',
paisCuba_historia_cronologia_2_texto: 'Cuba se independiza da Espanha após a Guerra Hispano-Americana. A Emenda Platt dá aos EUA o direito de intervenção.',
paisCuba_historia_cronologia_3_titulo: 'Revolução cubana',
paisCuba_historia_cronologia_3_texto: 'Fidel Castro e o Movimento 26 de Julho derrubam Fulgencio Batista. Início do governo revolucionário.',
paisCuba_practica_titulo: 'Informações Práticas',
paisCuba_practica_descripcion: 'Moeda, transporte, clima, vistos e conectividade para planejar sua viagem a Cuba.',
paisCuba_practica_infoCards_0_titulo: 'Moeda',
paisCuba_practica_infoCards_0_texto: 'Peso cubano (CUP). 1 USD ≈ 24 CUP. A moeda conversível (CUC) não circula mais.',
paisCuba_practica_infoCards_1_titulo: 'Como chegar',
paisCuba_practica_infoCards_1_texto: 'Aeroporto José Martí (HAV) em Havana. Aeroporto Juan Gualberto Gómez (VRA) em Varadero.',
paisCuba_practica_infoCards_2_titulo: 'Clima',
paisCuba_practica_infoCards_2_texto: 'Tropical, quente e úmido: 22-32°C. Temporada de furacões: junho-novembro.',
paisCuba_practica_infoCards_3_titulo: 'Vistos',
paisCuba_practica_infoCards_3_texto: 'É necessária a Tarjeta del Turista (visto de turismo). Os EUA têm restrições especiais.',
paisCuba_practica_infoCards_4_titulo: 'Conectividade',
paisCuba_practica_infoCards_4_texto: 'Conectividade variável. Melhor nas cidades e polos turísticos. Cartões de WiFi em parques.',
paisCuba_practica_infoCards_5_titulo: 'Hospedagem',
paisCuba_practica_infoCards_5_texto: 'Casas particulares (15-40 USD), hotéis 3* a partir de 50 USD, resorts a partir de 100 USD.',
