paisCuba_practica_itinerario_0_texto: 'Habana Vieja, Malecón, Capitólio, Vedado, Fábrica de Arte Cubano, Museu da Revolução.',
paisCuba_practica_itinerario_1_titulo: 'Vale de Viñales',
paisCuba_practica_itinerario_1_texto: 'Mogotes, plantações de tabaco, cavernas, cavalgadas.',
