paisCuba_practica_itinerario_4_texto: 'Castelo do Morro, Casa da Trova, Cemitério Santa Ifigenia.',
paisCuba_practica_itinerario_5_titulo: 'Retorno',
paisCuba_practica_itinerario_5_texto: 'Voo de Havana.',
paisCuba_practica_temporadas_0_nombre: 'Alta temporada',
paisCuba_practica_temporadas_0_descripcion: 'Clima mais seco, menos chuvas. Mais turistas e preços altos.',
paisCuba_practica_temporadas_1_nombre: 'Baixa temporada',
paisCuba_practica_temporadas_1_descripcion: 'Possíveis chuvas e furacões (set-nov). Menos turistas, melhores preços.',
paisCuba_guias_0_name: 'Alicia Pérez',
paisCuba_guias_0_description: 'Guia cultural em Havana. Especialista no centro histórico, no Malecón e na música cubana. Fala francês e inglês.',
paisCuba_guias_1_name: 'Manuel Gómez',
paisCuba_guias_1_description: 'Guia em Trinidad. Conhece cada canto da cidade colonial, o Vale dos Engenhos e a história dos escravos. Fala italiano e inglês.',
paisCuba_guias_2_name: 'Yolanda Sánchez',
paisCuba_guias_2_description: 'Guia em Viñales. Descendente de camponeses produtores de tabaco, compartilha a cultura do tabaco, os mogotes e as cavernas.',
paisCuba_guias_3_name: 'Raúl Martínez',
paisCuba_guias_3_description: 'Guia em Santiago de Cuba. Especialista em trova, carnaval e história revolucionária. Fala alemão e inglês.',
paisCuba_guias_4_name: 'Marta Jiménez',
paisCuba_guias_4_description: 'Guia em Varadero. Especialista em praias, snorkel, resorts e atividades aquáticas. Conhece os melhores pontos do litoral.',
paisCuba_guias_5_name: 'José Ramón',
paisCuba_guias_5_description: 'Guia em Baracoa. Especialista na cultura do cacau, em El Yunque e nas praias virgens. Fala português e inglês.',
