paisBolivia_aventura_titulo: 'Aventura & Natureza na Bolívia',
paisBolivia_aventura_descripcion: 'A Bolívia oferece uma das paisagens mais variadas da América do Sul: altiplano (4.000 m), montanhas (Sajama 6.542 m), salares (Uyuni), lagos (Titicaca), floresta amazônica (60% do território) e savanas.',
paisBolivia_aventura_stats_0_label: 'Sajama',
paisBolivia_aventura_stats_1_label: 'Salar de Uyuni',
