paisBolivia_aventura_stats_3_label: 'Parques nacionais',
paisBolivia_aventura_actividades_0_nombre: 'Excursão ao Salar de Uyuni',
paisBolivia_aventura_actividades_0_descripcion: 'Passeios de 1 a 3 dias pelo maior deserto de sal do mundo. Laguna Colorada, Laguna Verde, ilha Incahuasi, cemitério de trens.',
paisBolivia_aventura_actividades_1_nombre: 'Visita ao Lago Titicaca',
paisBolivia_aventura_actividades_1_descripcion: 'Ilha do Sol (ruínas incas, caminhadas), Ilha da Lua, Copacabana (Basílica). Um dos lagos mais altos do mundo.',
