paisBolivia_aventura_actividades_2_descripcion: 'Sucre (Casa de la Libertad, Parque Cretácico). Potosí (Cerro Rico, Casa da Moeda). Cidades Patrimônio da UNESCO.',
paisBolivia_aventura_actividades_3_nombre: 'Trekking na Cordilheira Real',
paisBolivia_aventura_actividades_3_descripcion: 'Cordilheira Real com picos acima de 6.000 m (Illimani, Huayna Potosí). Ascensões técnicas e trekking ao redor de La Paz.',
paisBolivia_aventura_actividades_4_nombre: 'Exploração da Amazônia boliviana',
paisBolivia_aventura_actividades_4_descripcion: 'Parque Nacional Madidi (uma das reservas mais biodiversas do mundo). Rurrenabaque (porta de entrada para a Amazônia e os Pampas).',
paisBolivia_aventura_actividades_5_nombre: 'Parque Nacional Sajama',
paisBolivia_aventura_actividades_5_descripcion: 'Vulcão mais alto da Bolívia (6.542 m). Florestas de queñua. Águas termais. Alpacas e vicunhas.',
paisBolivia_aventura_darkBand_titulo: 'Coração da América do Sul',
paisBolivia_aventura_darkBand_texto: 'A Bolívia tem o maior deserto de sal do mundo (Salar de Uyuni), o lago navegável mais alto (Titicaca), 60% do seu território é Amazônia e abriga 22 parques nacionais.',
