paisBolivia_historia_cronologia_0_texto: 'Simón Bolívar lidera a independência do Alto Peru. O país leva o seu nome.',
paisBolivia_historia_cronologia_1_titulo: 'Revolução Nacional',
paisBolivia_historia_cronologia_1_texto: 'Reforma agrária, nacionalização das minas e voto universal. Fim da oligarquia mineradora.',
