paisBolivia_practica_descripcion: 'Moeda, transporte, clima, vistos e conectividade para planejar sua viagem à Bolívia.',
paisBolivia_practica_infoCards_0_titulo: 'Moeda',
paisBolivia_practica_infoCards_0_texto: 'Boliviano (BOB). 1 USD ≈ 6,90 BOB (junho de 2026).',
paisBolivia_practica_infoCards_1_titulo: 'Como chegar',
paisBolivia_practica_infoCards_1_texto: 'Aeroporto El Alto (LPB) em La Paz. Aeroporto Viru Viru (VVI) em Santa Cruz. Aeroporto Jorge Wilstermann (CBB) em Cochabamba.',
paisBolivia_practica_infoCards_2_titulo: 'Clima',
paisBolivia_practica_infoCards_2_texto: 'Altiplano: 0-15°C (noites frias). Vales: 15-25°C. Amazônia: 22-35°C.',
paisBolivia_practica_infoCards_3_titulo: 'Vistos',
paisBolivia_practica_infoCards_3_texto: 'EUA, Canadá, UE, América Latina: sem visto para turismo (30-90 dias).',
paisBolivia_practica_infoCards_4_titulo: 'Conectividade',
paisBolivia_practica_infoCards_4_texto: 'Boa nas cidades (La Paz, Santa Cruz, Cochabamba, Sucre). Limitada na Amazônia e no Altiplano.',
paisBolivia_practica_infoCards_5_titulo: 'Hospedagem',
paisBolivia_practica_infoCards_5_texto: 'Hostels a partir de 10 USD, hotéis 3* a partir de 35 USD, lodges em Uyuni a partir de 50 USD.',
paisBolivia_practica_itinerario_0_titulo: 'La Paz',
paisBolivia_practica_itinerario_0_texto: 'Teleférico, Mercado das Bruxas, Vale da Lua, luta de cholita.',
