paisBolivia_practica_itinerario_2_texto: 'Tour de 3 dias: Salar, lagoas, ilha Incahuasi, cemitério de trens.',
paisBolivia_practica_itinerario_3_titulo: 'Sucre e Potosí',
paisBolivia_practica_itinerario_3_texto: 'Sucre (Casa de la Libertad, Parque Cretácico). Potosí (Cerro Rico, Casa da Moeda).',
paisBolivia_practica_itinerario_4_titulo: 'Retorno',
paisBolivia_practica_itinerario_4_texto: 'Voo de La Paz ou Santa Cruz.',
paisBolivia_practica_temporadas_0_nombre: 'Alta temporada (seca)',
paisBolivia_practica_temporadas_0_descripcion: 'Clima seco no Altiplano e nos Andes. Ideal para o Salar de Uyuni (efeito de sal). Dias ensolarados, noites frias.',
paisBolivia_practica_temporadas_1_nombre: 'Temporada de chuvas',
paisBolivia_practica_temporadas_1_descripcion: 'Chuvas no Altiplano e na Amazônia. Salar de Uyuni: efeito espelho (dezembro-abril). Caminhadas mais difíceis.',
paisBolivia_guias_0_name: 'Mama Julia Quispe',
paisBolivia_guias_0_description: 'Guia aimará em La Paz. Especialista no teleférico, no Mercado das Bruxas e na cultura andina. Compartilha as tradições do seu povo com paixão.',
paisBolivia_guias_1_name: 'Mario Cárdenas',
paisBolivia_guias_1_description: 'Guia no Salar de Uyuni. Conhece cada canto do deserto de sal, as lagoas e os melhores pontos fotográficos. Fala quíchua e inglês.',
paisBolivia_guias_2_name: 'Ana María Prado',
paisBolivia_guias_2_description: 'Guia em Sucre. Especialista em história colonial, na Casa de la Libertad e no Parque Cretácico. Fala francês e inglês.',
paisBolivia_guias_3_name: 'Pedro Mamani',
paisBolivia_guias_3_description: 'Guia em Copacabana. Conhece o Lago Titicaca, a Ilha do Sol e a cultura inca. Fala português e inglês.',
paisBolivia_guias_4_name: 'Rosa Flores',
paisBolivia_guias_4_description: 'Guia em Potosí. Especialista no Cerro Rico, na Casa da Moeda e na história mineradora. Compartilha a vida dos mineiros.',
paisBolivia_guias_5_name: 'Carlos Suárez',
paisBolivia_guias_5_description: 'Guia em Santa Cruz. Especialista no Parque Amboró, no Biocentro Güembé e na natureza da região. Fala alemão e inglês.',
