paisVenezuela_nombre: 'Venezuela',
paisVenezuela_subtitulo: 'Caribenha',
paisVenezuela_tagline: 'Terra de contrastes, ritmos e paisagens naturais',
paisVenezuela_descripcion: 'A Venezuela fica no norte da América do Sul e combina costas caribenhas, montanhas andinas, planícies e florestas amazônicas. É um país de grande diversidade geográfica e cultural, com uma população ampla e uma identidade muito marcada pela sua história, música e natureza.',
