paisVenezuela_souvenirs_1_productos_0_nombre: 'Poncho de Lã de Ovelha',
paisVenezuela_souvenirs_1_productos_0_descripcion: 'Poncho de lã de ovelha, tecido por artesãos dos Andes. Quente e colorido, ideal para o clima de montanha.',
