paisVenezuela_souvenirs_2_productos_1_descripcion: 'Figura esculpida em coco, representando a fauna e a flora do Caribe. Artesanato típico da Ilha de Margarita.',
paisVenezuela_souvenirs_2_productos_2_nombre: 'Pulseira de Fio Colorido',
paisVenezuela_souvenirs_2_productos_2_descripcion: 'Pulseira de fio colorido, com desenhos do Caribe. Feita por artesãos da região.',
paisVenezuela_souvenirs_2_productos_3_nombre: 'Jarro de Barro de Margarita',
paisVenezuela_souvenirs_2_productos_3_descripcion: 'Jarro de barro da Ilha de Margarita, com desenhos da flora e da fauna caribenha. Peça única da tradição oleira.',
paisVenezuela_souvenirs_2_productos_4_nombre: 'Memorial da Ilha',
paisVenezuela_souvenirs_2_productos_4_descripcion: 'Lembrança da Ilha de Margarita com paisagens da praia El Agua e do Farol de Punta Ballenas.',
paisVenezuela_aerolineas_0_descripcion: 'A companhia aérea de bandeira da Venezuela. Conexões nacionais e internacionais para destinos nas Américas e na Europa.',
paisVenezuela_aerolineas_1_descripcion: 'Companhia aérea venezuelana com voos domésticos para todo o país. Tarifas competitivas e boa cobertura nacional.',
paisVenezuela_aerolineas_2_descripcion: 'Conexões via Panamá para toda a América Latina. O Hub das Américas conecta a todos os destinos da Copa.',
paisVenezuela_aerolineas_3_descripcion: 'Voos diretos de Miami para Caracas. Conexões para toda a Venezuela e a América do Sul.',
paisVenezuela_aerolineas_4_descripcion: 'Companhia aérea venezuelana com voos nacionais e regionais. Conexões para a Colômbia, o Panamá e o Caribe.',
paisVenezuela_hospedajes_0_nombre: 'Casa na Montanha - Ávila, Caracas',
paisVenezuela_hospedajes_0_tipo: 'Casa inteira',
paisVenezuela_hospedajes_0_descripcion: 'Casa no Parque Nacional Ávila. Vista para a cidade de Caracas, rodeada de natureza e trilhas.',
paisVenezuela_hospedajes_1_nombre: 'Apartamento Moderno em Altamira',
paisVenezuela_hospedajes_1_tipo: 'Apartamento inteiro',
paisVenezuela_hospedajes_1_descripcion: 'Apartamento moderno no bairro mais exclusivo de Caracas. Perto de restaurantes, shoppings e vida noturna.',
paisVenezuela_hospedajes_2_nombre: 'Eco-lodge em Canaima',
paisVenezuela_hospedajes_2_tipo: 'Cabana ecológica',
paisVenezuela_hospedajes_2_descripcion: 'Eco-lodge na porta de entrada do Salto Ángel. Rodeado de selva e lagoas, com atividades de ecoturismo.',
paisVenezuela_hospedajes_3_nombre: 'Cabana Andina em Mérida',
paisVenezuela_hospedajes_3_tipo: 'Cabana privada',
paisVenezuela_hospedajes_3_descripcion: 'Cabana de madeira nos Andes venezuelanos. Lareira, terraço com vista para a montanha e clima fresco.',
paisVenezuela_hospedajes_4_nombre: 'Casa em Los Roques',
paisVenezuela_hospedajes_4_tipo: 'Casa na praia',
paisVenezuela_hospedajes_4_descripcion: 'Casa no Gran Roque, de frente para o mar. Terraço com vista para o Caribe, acesso a praias e atividades de mergulho.',
paisVenezuela_hospedajes_5_nombre: 'Cabana em Morrocoy',
paisVenezuela_hospedajes_5_tipo: 'Cabana costeira',
paisVenezuela_hospedajes_5_descripcion: 'Cabana perto dos caios de Morrocoy. Piscina, jardim tropical e acesso aos melhores pontos do parque nacional.',
paisUruguay_nombre: 'Uruguai',
paisUruguay_subtitulo: 'Serena',
paisUruguay_tagline: 'Terra de costa, calma e qualidade de vida',
paisUruguay_descripcion: 'O Uruguai fica no sudeste da América do Sul e se destaca pelo tamanho compacto, pelo litoral atlântico e pela estabilidade social e política. Tem uma população de pouco mais de 3,4 milhões de habitantes, capital em Montevidéu, moeda peso uruguaio e idioma oficial espanhol.',
paisUruguay_continente: 'América do Sul',
paisUruguay_moneda: 'Peso uruguaio (UYU)',
paisUruguay_idioma: 'Espanhol',
paisUruguay_capital: 'Montevidéu',
paisUruguay_poblacion: '3.400.000',
paisUruguay_zona_horaria: 'UTC-3',
paisUruguay_codigo_telefonico: '+598',
paisUruguay_stats_0_label: 'km² de território',
