paisUruguay_aventura_actividades_0_nombre: 'Praia e descanso em Punta del Este',
paisUruguay_aventura_actividades_0_descripcion: 'Praias Brava e Mansa, La Mano, Casapueblo, passeio de barco até a Ilha de Lobos. Resorts de luxo e vida noturna.',
paisUruguay_aventura_actividades_1_nombre: 'Passeio histórico por Colônia',
paisUruguay_aventura_actividades_1_descripcion: 'Bairro histórico Patrimônio UNESCO, ruas de pedra, farol, muralhas, museus. Ideal para caminhar e tirar fotos.',
paisUruguay_aventura_actividades_2_nombre: 'Observação de fauna em Cabo Polônio',
paisUruguay_aventura_actividades_2_descripcion: 'Lobos-marinhos, farol, dunas, praias virgens. Vila sem carros. Ambiente rústico e natureza pura.',
paisUruguay_aventura_actividades_3_nombre: 'Turismo termal em Salto',
paisUruguay_aventura_actividades_3_descripcion: 'Termas del Daymán (piscinas termais ao ar livre) e Arapey (mais exclusivas). Água quente natural 38-42°C.',
paisUruguay_aventura_actividades_4_nombre: 'Caminhadas pela costa em Montevidéu',
paisUruguay_aventura_actividades_4_descripcion: 'Rambla de 22 km, Cidade Velha, Mercado do Porto, praia urbana de Pocitos.',
paisUruguay_aventura_actividades_5_nombre: 'Passeios rurais e ao campo',
paisUruguay_aventura_actividades_5_descripcion: 'Estâncias no interior (Tacuarembó, Durazno). Cavalgadas, gastronomia crioula, contato com a natureza.',
paisUruguay_aventura_darkBand_titulo: 'Suíça da América',
paisUruguay_aventura_darkBand_texto: 'O Uruguai é conhecido como a \'Suíça da América\' por sua estabilidade política, institucionalidade, baixa corrupção e qualidade de vida. É o país com o maior consumo per capita de carne do mundo e o carnaval mais longo do planeta (40 dias).',
paisUruguay_aventura_darkBand_datos_0_label: 'km de costa',
