paisParaguay_practica_infoCards_0_texto: 'Guarani (PYG). 1 USD ≈ 7.400 PYG (junho de 2026).',
paisParaguay_practica_infoCards_1_titulo: 'Como chegar',
paisParaguay_practica_infoCards_1_texto: 'Aeroporto Internacional Silvio Pettirossi (ASU) em Assunção. Voos da América do Sul.',
paisParaguay_practica_infoCards_2_titulo: 'Clima',
paisParaguay_practica_infoCards_2_texto: 'Subtropical a quente: verão 25-38°C (out-mar). Inverno 10-25°C (abr-set).',
paisParaguay_practica_infoCards_3_titulo: 'Vistos',
paisParaguay_practica_infoCards_3_texto: 'EUA, Canadá, UE, América Latina: sem visto para turismo (30-90 dias).',
paisParaguay_practica_infoCards_4_titulo: 'Conectividade',
paisParaguay_practica_infoCards_4_texto: 'Boa nas cidades (Assunção, Encarnación, Ciudad del Este). Limitada no Chaco.',
paisParaguay_practica_infoCards_5_titulo: 'Hospedagem',
paisParaguay_practica_infoCards_5_texto: 'Hostels a partir de 20 USD, hotéis 3* a partir de 45 USD, eco-lodges no Chaco a partir de 60 USD.',
