paisParaguay_practica_itinerario_1_texto: 'Trinidad, Jesús de Tavarangüé, costanera de Encarnación.',
paisParaguay_practica_itinerario_2_titulo: 'Ciudad del Este e Saltos del Monday',
paisParaguay_practica_itinerario_2_texto: 'Itaipu, compras em free shops, cachoeira Monday.',
paisParaguay_practica_itinerario_3_titulo: 'Ybycuí ou Chaco',
paisParaguay_practica_itinerario_3_texto: 'Parque Nacional Ybycuí (cachoeiras, trilhas) ou exploração do Chaco.',
paisParaguay_practica_itinerario_4_titulo: 'Retorno',
paisParaguay_practica_itinerario_4_texto: 'Voo a partir de Assunção.',
paisParaguay_practica_temporadas_0_nombre: 'Temporada alta (inverno)',
paisParaguay_practica_temporadas_0_descripcion: 'Clima mais fresco, ideal para turismo cultural e de natureza.',
paisParaguay_practica_temporadas_1_nombre: 'Temporada alta (verão)',
paisParaguay_practica_temporadas_1_descripcion: 'Ideal para as praias de rio em Encarnación. Carnaval encarnaceno.',
paisParaguay_practica_temporadas_2_nombre: 'Recomendada',
paisParaguay_practica_temporadas_2_descripcion: 'Clima agradável, menos extremo. Bom momento para explorar.',
paisParaguay_guias_0_name: 'Miriam Benítez',
paisParaguay_guias_0_description: 'Guia em Assunção. Especialista no Centro Histórico, no Palácio dos López e na cultura guarani. Fala inglês e guarani.',
