paisParaguay_hospedajes_3_tipo: 'Apartamento inteiro',
paisParaguay_hospedajes_3_descripcion: 'Apartamento moderno no centro comercial de Ciudad del Este. Perto de free shops e da fronteira com o Brasil.',
paisParaguay_hospedajes_4_nombre: 'Cabana em Ybycuí',
paisParaguay_hospedajes_4_tipo: 'Cabana rústica',
paisParaguay_hospedajes_4_descripcion: 'Cabana no Parque Nacional Ybycuí. Cercada de natureza, cachoeiras e trilhas. Piscina natural.',
paisParaguay_hospedajes_5_nombre: 'Estância no Chaco',
paisParaguay_hospedajes_5_tipo: 'Cabana rural',
paisParaguay_hospedajes_5_descripcion: 'Estância no coração do Chaco paraguaio. Cabanas rústicas, observação de fauna e paisagens abertas.',
paisHonduras_nombre: 'Honduras',
paisHonduras_subtitulo: 'Íslaria',
paisHonduras_tagline: 'Terra de ilhas, cultura maia e praias caribenhas',
paisHonduras_descripcion: 'Honduras está no coração da América Central e se destaca pela riqueza natural, pelas ruínas maias e pelas praias caribenhas. Tem capital em Tegucigalpa, moeda lempira e idioma oficial espanhol.',
paisHonduras_continente: 'América Central',
paisHonduras_moneda: 'Lempira (HNL)',
paisHonduras_idioma: 'Espanhol',
paisHonduras_capital: 'Tegucigalpa',
