paisHonduras_ticker_0: 'Copán Ruínas | A \'Paris do mundo maia\'',
paisHonduras_ticker_1: 'Roatán | Recife Mesoamericano, o segundo maior do mundo',
paisHonduras_ticker_2: 'Utila | Mergulho econômico e avistamento de tubarões-baleia',
paisHonduras_ticker_3: 'Ilhas da Baía | Arquipélago caribenho',
paisHonduras_ticker_4: 'La Ceiba | Porta de entrada para a mata e o Parque Nacional Pico Bonito',
paisHonduras_ticker_5: 'Lempira | Moeda nomeada em homenagem ao cacique Lempira',
