paisHonduras_gastronomia_platos_1_categoria: 'Sopa · Litoral',
paisHonduras_gastronomia_platos_1_descripcion: 'Sopa de caracol (molusco marinho) em leite de coco, com mandioca, banana, legumes e especiarias. Tradicional no litoral caribenho.',
paisHonduras_gastronomia_platos_1_nota: 'Popular em Roatán e La Ceiba',
