paisHonduras_gastronomia_platos_2_categoria: 'Acompanhamento · Sobremesa',
paisHonduras_gastronomia_platos_2_descripcion: 'Banana madura frita e regada com mel de rapadura (açúcar). Sobremesa ou acompanhamento doce.',
paisHonduras_gastronomia_platos_2_nota: 'Com queijo fresco',
