paisHonduras_gastronomia_platos_3_categoria: 'Natal',
paisHonduras_gastronomia_platos_3_descripcion: 'Massa de milho recheada com carne bovina ou frango, azeitonas e passas, envolta em folha de bananeira. Muito populares no Natal.',
paisHonduras_gastronomia_platos_3_nota: 'Em folha de bananeira',
paisHonduras_gastronomia_platos_4_nombre: 'Mandioca com torresmo',
paisHonduras_gastronomia_platos_4_categoria: 'Prato do litoral',
paisHonduras_gastronomia_platos_4_descripcion: 'Mandioca cozida com torresmo de porco frito, servida com molho curtido (pimentas, cebola). Clássico do litoral.',
paisHonduras_gastronomia_platos_4_nota: 'Com molho curtido',
paisHonduras_gastronomia_platos_5_nombre: 'Suyas',
paisHonduras_gastronomia_platos_5_categoria: 'Espetinhos',
paisHonduras_gastronomia_platos_5_descripcion: 'Espetinhos de carne bovina, frango ou porco marinados em especiarias e assados no carvão.',
paisHonduras_gastronomia_platos_5_nota: 'Em carrinhos',
paisHonduras_gastronomia_platos_6_nombre: 'Olla de carne',
paisHonduras_gastronomia_platos_6_categoria: 'Sopa farta',
paisHonduras_gastronomia_platos_6_descripcion: 'Sopa de carne bovina com mandioca, banana, batata, milho verde e legumes.',
paisHonduras_gastronomia_platos_6_nota: 'Aos domingos',
