paisHonduras_gastronomia_platos_7_categoria: 'Molho',
paisHonduras_gastronomia_platos_7_descripcion: 'Molho de tomate assado, pimenta verde, cebola e coentro.',
paisHonduras_gastronomia_platos_7_nota: 'Acompanha carnes e baleadas',
paisHonduras_gastronomia_platos_8_nombre: 'Rondabolla',
paisHonduras_gastronomia_platos_8_categoria: 'Empanada de milho',
paisHonduras_gastronomia_platos_8_descripcion: 'Empanada de milho recheada com carne moída, ovo cozido, cebola, pimenta e especiarias.',
paisHonduras_gastronomia_platos_8_nota: 'Especialidade garífuna',
