paisHonduras_aventura_titulo: 'Aventura & Natureza em Honduras',
paisHonduras_aventura_descripcion: 'Honduras oferece recifes de coral (Recife Mesoamericano), florestas (Pico Bonito, Mosquitia), montanhas (Cerro Las Minas 2,870 m), rios para rafting e litorais caribenhos.',
paisHonduras_aventura_stats_0_label: 'km de litoral caribenho',
paisHonduras_aventura_stats_1_label: 'Cerro Las Minas',
paisHonduras_aventura_stats_2_label: 'Parques nacionais',
paisHonduras_aventura_stats_3_label: 'maior recife do mundo',
paisHonduras_aventura_actividades_0_nombre: 'Mergulho em Roatán e Utila',
paisHonduras_aventura_actividades_0_descripcion: 'Recife Mesoamericano (segundo maior do mundo). Tubarões-baleia em Utila (março-abril, agosto-setembro). Snorkel em Cayos Cochinos.',
paisHonduras_aventura_actividades_1_nombre: 'Visita a Copán',
paisHonduras_aventura_actividades_1_descripcion: 'Ruínas maias Patrimônio UNESCO. Escadaria dos Hieróglifos. Túnel arqueológico. Museu da Escultura Maia.',
paisHonduras_aventura_actividades_2_nombre: 'Rafting no Rio Cangrejal',
paisHonduras_aventura_actividades_2_descripcion: 'Rafting classe III-IV perto de La Ceiba. Floresta, cachoeiras e desfiladeiros. Para aventureiros experientes.',
paisHonduras_aventura_actividades_3_nombre: 'Trilhas em Pico Bonito',
paisHonduras_aventura_actividades_3_descripcion: 'Parque Nacional com floresta tropical. Trilhas até cachoeiras (El Bejuco, Zacate). Aves (quetzal, tucano, arara).',
paisHonduras_aventura_actividades_4_nombre: 'Praias nas Ilhas da Baía',
paisHonduras_aventura_actividades_4_descripcion: 'West Bay (Roatán). Praias de areia branca e águas turquesa. Snorkel a partir da praia. Relaxamento.',
paisHonduras_aventura_actividades_5_nombre: 'Turismo cultural em Tegucigalpa',
paisHonduras_aventura_actividades_5_descripcion: 'Catedral, Parque Nacional La Tigra, Museu da Identidade Nacional. Cidade com história colonial.',
paisHonduras_aventura_darkBand_titulo: 'Terra do recife mesoamericano e de Copán',
paisHonduras_aventura_darkBand_texto: 'Honduras tem o segundo maior recife de coral do mundo (Recife Mesoamericano) e as ruínas maias mais finamente trabalhadas da civilização maia (Copán). 60% do seu território é montanhoso e 8 parques nacionais protegem sua biodiversidade.',
