paisHonduras_historia_descripcion: 'Do esplendor maia em Copán à independência centro-americana.',
paisHonduras_historia_cronologia_0_titulo: 'Chegada espanhola',
paisHonduras_historia_cronologia_0_texto: 'Cristóbal de Olid funda Triunfo de la Cruz. Início da colonização espanhola.',
paisHonduras_historia_cronologia_1_titulo: 'Independência da América Central',
paisHonduras_historia_cronologia_1_texto: 'Honduras se torna independente da Espanha junto com as províncias centro-americanas.',
paisHonduras_historia_cronologia_2_titulo: 'Independência total',
paisHonduras_historia_cronologia_2_texto: 'Honduras se separa da Federação Centro-Americana e se torna uma república independente.',
paisHonduras_practica_titulo: 'Informações Práticas',
paisHonduras_practica_descripcion: 'Moeda, transporte, clima, vistos e conectividade para planejar sua viagem a Honduras.',
paisHonduras_practica_infoCards_0_titulo: 'Moeda',
paisHonduras_practica_infoCards_0_texto: 'Lempira (HNL). 1 USD ≈ 25 HNL (junho de 2026).',
paisHonduras_practica_infoCards_1_titulo: 'Como chegar',
paisHonduras_practica_infoCards_1_texto: 'Aeroporto Internacional Toncontín (TGU) em Tegucigalpa. Aeroporto Ramón Villeda Morales (SAP) em San Pedro Sula.',
paisHonduras_practica_infoCards_2_titulo: 'Clima',
paisHonduras_practica_infoCards_2_texto: 'Tropical no litoral (25-35°C). Temperado nas montanhas (15-25°C).',
paisHonduras_practica_infoCards_3_titulo: 'Vistos',
paisHonduras_practica_infoCards_3_texto: 'EUA, Canadá, UE, América Latina: sem visto para turismo (30-90 dias).',
paisHonduras_practica_infoCards_4_titulo: 'Conectividade',
paisHonduras_practica_infoCards_4_texto: 'Boa nas cidades (Tegucigalpa, San Pedro Sula, La Ceiba). Limitada nas ilhas e na selva.',
paisHonduras_practica_infoCards_5_titulo: 'Hospedagem',
paisHonduras_practica_infoCards_5_texto: 'Hostels a partir de 20 USD, hotéis 3* a partir de 45 USD, resorts em Roatán a partir de 80 USD.',
paisHonduras_practica_itinerario_0_titulo: 'Tegucigalpa',
paisHonduras_practica_itinerario_0_texto: 'Catedral, Parque Nacional La Tigra, Museu da Identidade Nacional.',
paisHonduras_practica_itinerario_1_titulo: 'Copán Ruinas',
paisHonduras_practica_itinerario_1_texto: 'Acrópole, Escadaria, Museu, estelas.',
paisHonduras_practica_itinerario_2_titulo: 'Roatán e Utila',
paisHonduras_practica_itinerario_2_texto: 'Mergulho, snorkel, praias, West Bay, tubarões-baleia.',
paisHonduras_practica_itinerario_3_titulo: 'La Ceiba e Pico Bonito',
paisHonduras_practica_itinerario_3_texto: 'Rafting em Cangrejal, trilhas em Pico Bonito.',
paisHonduras_practica_itinerario_4_titulo: 'Retorno',
paisHonduras_practica_itinerario_4_texto: 'Voo a partir de San Pedro Sula ou Tegucigalpa.',
paisHonduras_practica_temporadas_0_nombre: 'Alta temporada (seca)',
paisHonduras_practica_temporadas_0_descripcion: 'Clima seco, ideal para praias e ruínas. Mais turistas.',
