paisHonduras_guias_0_description: 'Guia em Copán Ruinas. Especialista em arqueologia maia, na Escadaria dos Hieróglifos e no Museu da Escultura Maia. Fala maia e inglês.',
paisHonduras_guias_1_name: 'Carlos Mejía',
paisHonduras_guias_1_description: 'Guia em Roatán. Mergulhador profissional, conhece os melhores recifes e pontos de snorkel da ilha. Oferece tours personalizados.',
