paisHonduras_guias_3_description: 'Guia em Tegucigalpa. Conhece o centro histórico, o Parque Nacional La Tigra e a cultura da capital. Fala alemão e inglês.',
paisHonduras_guias_4_name: 'María Fernanda Vásquez',
