paisNicaragua_nombre: 'Nicarágua',
paisNicaragua_subtitulo: 'Vulcânica',
paisNicaragua_tagline: 'Terra de vulcões, lagos e praias caribenhas',
paisNicaragua_descripcion: 'A Nicarágua está no coração da América Central e se destaca pela sua geografia vulcânica, seus dois grandes lagos e suas costas no Pacífico e no Caribe. Tem a capital em Manágua, moeda córdoba e idioma oficial espanhol.',
paisNicaragua_continente: 'América Central',
paisNicaragua_moneda: 'Córdoba (NIO)',
