paisNicaragua_gastronomia_platos_3_descripcion: 'Mandioca cozida com torresmo de porco frito, servida com molho curtido (pimentas, cebola, vinagre).',
paisNicaragua_gastronomia_platos_3_nota: 'Popular nos cafés da manhã',
