paisNicaragua_gastronomia_platos_5_descripcion: 'Banana madura frita e coberta com mel de rapadura (açúcar). Sobremesa ou acompanhamento doce.',
paisNicaragua_gastronomia_platos_5_nota: 'Com queijo fresco',
