paisElSalvador_quickFacts_0_titulo: 'País compacto',
paisElSalvador_quickFacts_0_texto: 'El Salvador é o país mais pequeno da América Central (21.040 km²), mas muito ativo e dinâmico. É o segundo país mais densamente povoado da América (depois de Barbados).',
paisElSalvador_quickFacts_1_titulo: 'Vulcânica',
paisElSalvador_quickFacts_1_texto: 'Tem uma das maiores concentrações de vulcões ativos da região, incluindo o Vulcão de Santa Ana (2.381 m, o mais alto do país).',
paisElSalvador_quickFacts_2_titulo: 'Costa do Pacífico',
paisElSalvador_quickFacts_2_texto: 'Seu litoral no Pacífico, de 307 km, é muito conhecido por praias como El Tunco, El Zonte e Sunzal, famosas pelo surfe em nível mundial.',
paisElSalvador_quickFacts_3_titulo: 'Cultura viva',
paisElSalvador_quickFacts_3_texto: 'A música (marimba, cumbia), as festas patronais e a gastronomia (pupusas) são centrais no cotidiano salvadorenho.',
paisElSalvador_destinos_sansalvador_nombre: 'San Salvador',
paisElSalvador_destinos_sansalvador_tag: 'Urbano · Capital',
paisElSalvador_destinos_sansalvador_descripcion: 'Capital com vida moderna e história. Centro político e cultural. Fundada em 1525.',
paisElSalvador_destinos_sansalvador_detalle: 'Centro Histórico: Catedral Metropolitana, Palácio Nacional, Teatro Nacional. Praça Gerardo Barrios. Monumento ao Salvador do Mundo. Museu de Arte (MARTE). Parque Nacional El Boquerón (cratera do vulcão).',
paisElSalvador_destinos_sansalvador_consejo: 'Percorrer o centro histórico durante o dia',
paisElSalvador_destinos_santaana_nombre: 'Santa Ana',
paisElSalvador_destinos_santaana_tag: 'História · Colonial',
paisElSalvador_destinos_santaana_descripcion: 'Cidade colonial com arquitetura histórica. Famosa pelo seu teatro e praças. Segunda cidade mais importante de El Salvador.',
paisElSalvador_destinos_santaana_detalle: 'Teatro de Santa Ana (estilo renascentista). Catedral de Santa Ana. Paróquia El Calvario. Centro histórico. Rua da Amizade.',
paisElSalvador_destinos_santaana_consejo: 'Ideal para turismo cultural',
paisElSalvador_destinos_eltunco_nombre: 'Praia El Tunco',
paisElSalvador_destinos_eltunco_tag: 'Praia · Surfe · Pacífico',
paisElSalvador_destinos_eltunco_descripcion: 'Praia de rocha negra e surfe. Muito visitada por surfistas internacionais. Considerada a capital do surfe de El Salvador.',
paisElSalvador_destinos_eltunco_detalle: 'Ondas constantes para o surfe (iniciantes e especialistas). La Roca (formação rochosa no mar). Pôr do sol. Vida noturna. Restaurantes com frutos do mar.',
paisElSalvador_destinos_eltunco_consejo: 'Excelente para esportes aquáticos',
paisElSalvador_destinos_volcan_santaana_nombre: 'Vulcão de Santa Ana',
paisElSalvador_destinos_volcan_santaana_tag: 'Vulcão · Natureza',
paisElSalvador_destinos_volcan_santaana_descripcion: 'Vulcão ativo (2.381 m), o mais alto de El Salvador. Lago de cratera de cor turquesa. Ideal para trekking e vistas.',
paisElSalvador_destinos_volcan_santaana_detalle: 'Lago de cratera de cor turquesa. Mirante com vistas para o Lago de Coatepeque. Caminhada de 2-3 horas. Guia obrigatório.',
paisElSalvador_destinos_volcan_santaana_consejo: 'Levar casaco, água e protetor solar',
paisElSalvador_destinos_coatepeque_nombre: 'Lago de Coatepeque',
paisElSalvador_destinos_coatepeque_tag: 'Lago vulcânico · Relax',
paisElSalvador_destinos_coatepeque_descripcion: 'Lago de águas turquesa e cor mutável. Cratera vulcânica cheia de água. Muito bom para passeio de barco, esqui aquático e relaxar.',
paisElSalvador_destinos_coatepeque_detalle: 'Passeios de lancha. Restaurantes na margem (peixes e frutos do mar). Atividades aquáticas (esqui, jet ski). Ilha dos cavalos e ponto de mergulho.',
paisElSalvador_destinos_coatepeque_consejo: 'Perfeito para descanso e passeio',
paisElSalvador_destinos_juayua_nombre: 'Juayúa',
paisElSalvador_destinos_juayua_tag: 'Gastronomia · Vila',
paisElSalvador_destinos_juayua_descripcion: 'Vila na Rota das Flores (La Libertad). Muito famosa pela sua feira gastronômica de fim de semana.',
paisElSalvador_destinos_juayua_detalle: 'Feira gastronômica (sábados e domingos). Comida típica: pupusas, yuca com torresmo, carne assada, frutos do mar. Festival das flores. Cachoeiras próximas.',
paisElSalvador_destinos_juayua_consejo: 'Ideal para turismo de comida e cultura',
paisElSalvador_destinos_suchitoto_nombre: 'Suchitoto',
paisElSalvador_destinos_suchitoto_tag: 'História · Colonial · Lago',
paisElSalvador_destinos_suchitoto_descripcion: 'Vila colonial às margens do Lago Suchitlán. Ruas de paralelepípedos, igreja e vistas para o lago.',
paisElSalvador_destinos_suchitoto_detalle: 'Igreja Santa Lucía. Ruas de paralelepípedos. Museu da Palavra. Passeio de lancha pelo Lago Suchitlán. Cachoeira Los Tercios. Festival de arte.',
paisElSalvador_destinos_suchitoto_consejo: 'Passeio ao entardecer',
paisElSalvador_destinos_conchagua_nombre: 'Vulcão de Conchagua',
paisElSalvador_destinos_conchagua_tag: 'Vulcão · Vistas',
paisElSalvador_destinos_conchagua_descripcion: 'Vulcão (1.225 m) no Golfo de Fonseca (La Unión). Vistas panorâmicas das costas e do Golfo.',
paisElSalvador_destinos_conchagua_detalle: 'Vistas do Golfo de Fonseca (El Salvador, Honduras, Nicarágua). Trilhas. Observação de aves. Comunidades locais.',
paisElSalvador_cultura_titulo: 'Cultura Salvadorenha',
paisElSalvador_cultura_descripcion: 'A cultura salvadorenha mistura influências indígenas (pipil), africanas e europeias, com forte presença na música, nas festas, na gastronomia e no artesanato.',
paisElSalvador_cultura_stats_0_label: 'km² (país mais pequeno)',
