paisElSalvador_cultura_items_pupusas_nombre: 'Pupusas',
paisElSalvador_cultura_items_pupusas_tag: 'Gastronomia · Patrimônio',
paisElSalvador_cultura_items_pupusas_descripcion: 'Prato emblemático nacional. Tortilla de milho recheada com queijo, feijão, torresmo ou revolta. Acompanhada de curtido (repolho fermentado) e molho.',
paisElSalvador_cultura_items_pupusas_detalle: 'Declaradas Patrimônio Cultural de El Salvador. O Dia Nacional da Pupusa é no segundo domingo de novembro. As pupuserias estão em todo o país.',
paisElSalvador_cultura_items_marimba_nombre: 'Marimba Salvadorenha',
paisElSalvador_cultura_items_marimba_tag: 'Música',
paisElSalvador_cultura_items_marimba_descripcion: 'Instrumento tradicional em El Salvador. A cumbia salvadorenha é um gênero popular.',
paisElSalvador_cultura_items_marimba_detalle: 'A marimba de arco é característica salvadorenha. Presente em festas patronais e eventos cívicos. Companhias e bandas marciais.',
paisElSalvador_cultura_items_fiestas_nombre: 'Festa da Virgem da Paz',
paisElSalvador_cultura_items_fiestas_tag: 'Festividade',
paisElSalvador_cultura_items_fiestas_descripcion: 'Celebração muito popular em San Miguel (novembro). Procissão da Virgem da Paz, padroeira de El Salvador.',
paisElSalvador_cultura_items_fiestas_detalle: 'Uma das celebrações religiosas mais importantes da América Central. Procissão, música, dança, fogos de artifício. Representação de \'La Bajada\'.',
paisElSalvador_cultura_items_artesania_nombre: 'Artesanatos Salvadorenhos',
paisElSalvador_cultura_items_artesania_tag: 'Têxteis · Cerâmica',
paisElSalvador_cultura_items_artesania_descripcion: 'Têxteis, cerâmica, cestaria e trabalhos em madeira. A cidade de La Palma (Chalatenango) é centro artesanal.',
paisElSalvador_cultura_items_artesania_detalle: 'Pinturas de La Palma (estilo naif). Tecidos de San Sebastián. Cerâmica de Ilobasco (figuras de barro). Redes de San Juan Nonualco.',
paisElSalvador_cultura_darkBand_titulo: 'País das pupusas e do Bitcoin',
paisElSalvador_cultura_darkBand_texto: 'El Salvador é o país mais pequeno da América Central, mas o mais densamente povoado. Foi o primeiro país do mundo a adotar o Bitcoin como moeda de curso legal (2021). As pupusas são o seu prato emblemático.',
