paisElSalvador_aventura_darkBand_texto: 'El Salvador é conhecido como \'O Polegarzinho da América\' por ser o menor país da América Central, mas com alta densidade populacional. Tem 20 vulcões em seu território e uma das melhores costas de surfe do mundo.',
