paisBelice_aerolineas_0_descripcion: 'Conexões via Panamá para toda a América Latina. O Hub das Américas conecta com todos os destinos da Copa.',
paisBelice_aerolineas_1_descripcion: 'Voos diretos de Miami e Dallas para a Cidade de Belize. Ampla rede norte-americana.',
