paisGuyana_nombre: 'Guiana',
paisGuyana_subtitulo: 'Selvagem',
paisGuyana_tagline: 'Terra de selvas, cachoeiras e cultura caribenha',
paisGuyana_descripcion: 'A Guiana fica no norte da América do Sul e se destaca por suas extensas florestas tropicais, suas grandes cachoeiras e sua mistura de culturas. Tem a capital em Georgetown, moeda dólar guianês e idioma oficial inglês.',
paisGuyana_continente: 'América do Sul',
paisGuyana_moneda: 'Dólar guianês (GYD)',
paisGuyana_idioma: 'Inglês (oficial), crioulo guianês, línguas indígenas (karib, arawak, warao)',
