paisGuyana_quickFacts_0_titulo: 'Floresta extensa',
paisGuyana_quickFacts_0_texto: 'A Guiana tem uma das maiores concentrações de floresta tropical da América do Sul (aproximadamente 85% do seu território é floresta). É um dos países mais biodiversos do mundo.',
paisGuyana_quickFacts_1_titulo: 'Cachoeiras emblemáticas',
paisGuyana_quickFacts_1_texto: 'Kaieteur Falls (226 m de altura) é uma das cachoeiras mais altas do mundo. Tem uma queda única de mais de cinco vezes a altura das Cataratas do Niágara.',
paisGuyana_quickFacts_2_titulo: 'Cultura multiétnica',
paisGuyana_quickFacts_2_texto: 'A identidade do país mistura influências indígenas (arawak, karib, warao), africanas (descendentes de escravos), indianas (hindus) e europeias (holandesas, britânicas).',
paisGuyana_quickFacts_3_titulo: 'Inglês oficial',
paisGuyana_quickFacts_3_texto: 'A Guiana é um dos poucos países da América do Sul com inglês como idioma oficial (junto com a Guiana Francesa - francês, e o Suriname - holandês).',
paisGuyana_destinos_georgetown_nombre: 'Georgetown',
paisGuyana_destinos_georgetown_tag: 'Urbano · Colonial',
paisGuyana_destinos_georgetown_descripcion: 'Capital com arquitetura colonial holandesa. Centro político e cultural do país.',
paisGuyana_destinos_georgetown_detalle: 'Catedral de São Jorge (uma das igrejas de madeira mais altas do mundo). Prefeitura de Georgetown. Mercado Stabroek. Museu da Guiana. Promenade Garden. Prédios coloniais.',
paisGuyana_destinos_georgetown_consejo: 'Percorrer o centro histórico com guia',
paisGuyana_destinos_kaieteur_nombre: 'Cachoeira Kaieteur',
paisGuyana_destinos_kaieteur_tag: 'Natureza · Cachoeira',
paisGuyana_destinos_kaieteur_descripcion: 'Cachoeira mais alta do mundo em queda única (226 m). Localizada no Parque Nacional Kaieteur.',
paisGuyana_destinos_kaieteur_detalle: 'Queda única de 226 m. Parque Nacional Kaieteur (floresta tropical, bromélias, insetos, aves). Poesia de Sir Walter Raleigh. Vistas espetaculares.',
paisGuyana_destinos_kaieteur_consejo: 'Visitar com guia e planejar bem o transporte',
paisGuyana_destinos_iwokrama_nombre: 'Parque Nacional Iwokrama',
paisGuyana_destinos_iwokrama_tag: 'Natureza · Selva',
paisGuyana_destinos_iwokrama_descripcion: 'Reserva de floresta e biodiversidade de 371.000 hectares. Lar de onças, lontras gigantes e araras vermelhas.',
paisGuyana_destinos_iwokrama_detalle: 'Centro Iwokrama (hospedagem). Caminhadas na floresta. Avistamento de onças. Canopy walkway (passarela sobre o dossel). Lontras gigantes no rio Essequibo.',
paisGuyana_destinos_iwokrama_consejo: 'Excelente para ecoturismo',
paisGuyana_destinos_rupununi_nombre: 'Rupununi',
paisGuyana_destinos_rupununi_tag: 'Natureza · Savana',
paisGuyana_destinos_rupununi_descripcion: 'Zona de savanas no sudoeste da Guiana. Fauna sul-americana: tamanduás, onças, tatus, emas.',
paisGuyana_destinos_rupununi_detalle: 'Savanas abertas. Lethem (cidade fronteiriça com o Brasil). Fazendas (cattle ranches). Avistamento de fauna. Kawas, corubore.',
paisGuyana_destinos_rupununi_consejo: 'Perfeito para safári natural',
paisGuyana_destinos_berbice_nombre: 'Berbice',
paisGuyana_destinos_berbice_tag: 'Natureza · Rio',
paisGuyana_destinos_berbice_descripcion: 'Região com floresta e rio Berbice. Importante para o turismo interno, pesca e natureza.',
paisGuyana_destinos_berbice_detalle: 'Ponte Berbice. Pesca. Plantações. Floresta.',
paisGuyana_destinos_berbice_consejo: 'Boa base para explorar',
paisGuyana_destinos_kourou_nombre: 'Kourou (Guiana Francesa)',
paisGuyana_destinos_kourou_tag: 'Natureza',
paisGuyana_destinos_kourou_descripcion: 'Zona fronteiriça com a Guiana Francesa. Selva, cachoeiras.',
paisGuyana_destinos_kourou_detalle: 'Floresta tropical. Cachoeira. Comunidade local.',
paisGuyana_destinos_kourou_consejo: 'Ideal para caminhadas',
paisGuyana_destinos_kanuku_nombre: 'Montanhas Kanuku',
paisGuyana_destinos_kanuku_tag: 'Natureza · Montanha',
paisGuyana_destinos_kanuku_descripcion: 'Montanhas no sul da Guiana, perto da fronteira com o Brasil. Floresta tropical e biodiversidade.',
paisGuyana_destinos_kanuku_detalle: 'Caminhadas. Avistamento de fauna. Comunidades indígenas wapishana.',
paisGuyana_destinos_kanuku_consejo: 'Contratar guia local',
paisGuyana_destinos_shellbeach_nombre: 'Shell Beach',
paisGuyana_destinos_shellbeach_tag: 'Praia · Tartarugas',
paisGuyana_destinos_shellbeach_descripcion: 'Praia remota no noroeste da Guiana, conhecida pela nidificação de tartarugas marinhas.',
paisGuyana_destinos_shellbeach_detalle: 'Nidificação de tartarugas verdes, de pente, cabeçudas e leatherback (março-agosto). Conservação. Acesso difícil.',
paisGuyana_destinos_shellbeach_consejo: 'Temporada de tartarugas (março-agosto)',
paisGuyana_cultura_titulo: 'Cultura Guianense',
paisGuyana_cultura_descripcion: 'A cultura guianense mistura influências indígenas (arawak, karib, warao), africanas (descendentes de escravos), indianas (hindus chegados como trabalhadores contratados) e europeias (holandesas, britânicas). O inglês e o crioulo guianês são as principais línguas.',
