paisGuyana_cultura_items_creole_nombre: 'Crioulo Guianês',
paisGuyana_cultura_items_creole_tag: 'Língua · Identidade',
paisGuyana_cultura_items_creole_descripcion: 'Língua crioula de base inglesa, falada pela maioria da população no dia a dia.',
paisGuyana_cultura_items_creole_detalle: 'Mistura de inglês, línguas africanas, hindi e arawak. Frases comuns: \'How you dey?\' (como você está?).',
paisGuyana_cultura_items_mashramani_nombre: 'Mashramani',
paisGuyana_cultura_items_mashramani_tag: 'Festividade · República',
paisGuyana_cultura_items_mashramani_descripcion: 'Celebração do Dia da República (23 de fevereiro). Desfiles, música calipso, fantasias coloridas e dança.',
paisGuyana_cultura_items_mashramani_detalle: 'Mashramani significa \'celebração depois do trabalho duro\' em língua indígena. Semelhante ao carnaval.',
paisGuyana_cultura_items_curry_nombre: 'Curry guianês',
paisGuyana_cultura_items_curry_tag: 'Gastronomia',
paisGuyana_cultura_items_curry_descripcion: 'Prato típico de frango ou carne com especiarias. Influência indiana (hindu).',
paisGuyana_cultura_items_curry_detalle: 'Com roti.',
paisGuyana_cultura_items_indigenous_nombre: 'Povos Indígenas',
paisGuyana_cultura_items_indigenous_tag: 'Etnias · Arawak · Caribe · Warao',
paisGuyana_cultura_items_indigenous_descripcion: 'Nove povos indígenas: arawak (lokono), karib (kalina), warao, wapishana, macushi, akawaio, patamona, arekuna e shixiana.',
paisGuyana_cultura_items_indigenous_detalle: 'A cultura indígena inclui cestas, cerâmica, redes e artesanato. Cazabe (pão de mandioca).',
paisGuyana_cultura_darkBand_titulo: 'País de selvas e cultura caribenha',
paisGuyana_cultura_darkBand_texto: 'A Guiana é o único país sul-americano com inglês como idioma oficial. É membro da CARICOM (Comunidade do Caribe). Sua cultura é uma mistura única de influências indígenas, africanas, indianas e europeias.',
