paisGuyana_gastronomia_titulo: 'Gastronomia da Guiana',
paisGuyana_gastronomia_descripcion: 'A culinária guianense combina influências indígenas, africanas, indianas (hindus), europeias e caribenhas. Base em arroz, peixe, frango, banana-da-terra, mandioca e especiarias.',
